266  parse_sexp(s_exp_t *s_exp, const char **r_bytes, size_t *r_length)
   267  {
   268      size_t      length = *r_length;
   269      const char *bytes = *r_bytes;
   270
   271      s_exp_t new_s_exp = {0};
   272
   273      if (bytes == NULL || length == 0) {
   274          RNP_LOG("empty s-exp");
   275          return true;
   276      }
   277
   278      if (*bytes != '(') { // doesn't start from (
   279          return false;
   280      }
   281
   282      bytes++;
   283      length--;
   284
   285      do {
   286          if (length <= 0) { // unexpected end
   287              RNP_LOG("s-exp finished before ')'");
   288              destroy_s_exp(&new_s_exp);
   289              return false;
   290          }
   291
   292          if (*bytes == '(') {
   293              s_exp_t *new_sub_s_exp;
   294
   295              if (!add_sub_sexp_to_sexp(&new_s_exp, &new_sub_s_exp)) {
   296                  return false;
   297              }
   298
   299              if (!parse_sexp(new_sub_s_exp, &bytes, &length)) {
   300                  destroy_s_exp(&new_s_exp);
   301                  return false;
   302              }
   303
   304              continue;
   305          }
   306
   307          char *next;
   308          long  len = strtol(bytes, &next, 10);
   309
   310          if (*next != ':') { // doesn't contain :
   311              RNP_LOG("s-exp doesn't contain ':'");
   312              destroy_s_exp(&new_s_exp);
   313              return false;
   314          }
   315
   316          next++;
   317
   318          length -= (next - bytes);
   319          bytes = next;
   320
   321          if (len == LONG_MIN || len == LONG_MAX || len <= 0 || (size_t) len >= length) {
   322              RNP_LOG(
   323                "len over/under flow or bigger than remaining bytes, len: %ld, length: %zu",
   324                len,
   325                length);
   326              destroy_s_exp(&new_s_exp);
   327              return false;
   328          }
   329
   330          if (!add_block_to_sexp(&new_s_exp, (uint8_t *) bytes, (size_t) len)) {
   331              destroy_s_exp(&new_s_exp);
   332              return false;
   333          }
   334
   335          bytes += len;
   336          length -= len;
   337
   338      } while (*bytes != ')');
   339
   340      bytes++;
